def compute(vars):
    numerator = vars["v1"]
    denominator = vars["v2"]
    if denominator == 0:
        return {"value": None, "trace": {"output_meta": {"currency": None, "scale": "percent", "unit": "percentage"}}}
    ratio = numerator / denominator
    percentage = ratio * 100
    return {
        "value": percentage,
        "trace": {
            "numerator": numerator,
            "denominator": denominator,
            "ratio": ratio,
            "output_meta": {"currency": None, "scale": "percent", "unit": "percentage"}
        }
    }
